Brief: Tell me how MangoDB's indexes work and when a query uses them. — about serializeKeyValue (src/index-manager.ts)

1. * Serialize a key value for use as a map key.
2. private serializeKeyValue(value: unknown): string {
3. if (value === undefined) {
4. return JSON.stringify(null);
5. if (value !== null && typeof (value as { toHexString?: () => string }).toHexString === 'function') {
6. return JSON.stringify({ $oid: (value as { toHexString(): string }).toHexString() });
7. if (value instanceof Date) {
8. return JSON.stringify({ $date: value.toISOString() });
9. return JSON.stringify(value);

